fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // We consume both vectors and zip their elements together.
    // For each pair (x, y) we compute x & y, then collect into a new Vec<u8>.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x & y)
     .collect()
}

#[cfg(test)]
mod tests {
    use super::bitwise_and;

    #[test]
    fn test_empty() {
        let a = vec![];
        let b = vec![];
        let result = bitwise_and(a, b);
        assert_eq!(result, vec![]);
    }

    #[test]
    fn test_basic() {
        let a = vec![0b1010_1010, 0b1111_0000, 0b0000_1111];
        let b = vec![0b1100_1100, 0b1010_1010, 0b1111_0000];
        let result = bitwise_and(a, b);
        // 10101010 & 11001100 = 10001000 (0x88)
        // 11110000 & 10101010 = 10100000 (0xA0)
        // 00001111 & 11110000 = 00000000 (0x00)
        assert_eq!(result, vec![0x88, 0xA0, 0x00]);
    }

    #[test]
    fn test_all_ones() {
        let a = vec![0xFF, 0xFF, 0xFF];
        let b = vec![0x0F, 0xF0, 0xAA];
        let result = bitwise_and(a, b);
        assert_eq!(result, vec![0x0F, 0xF0, 0xAA]);
    }
}